local GildingBrushMaker = {}
local PRODUCTS = {
    iron_gildingbrush = { name = "Železni čopič za pozlačevanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni čopič za pozlačevanje za knjigoveze." },
    bronze_gildingbrush = { name = "Bronast čopič za pozlačevanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast čopič za pozlačevanje za knjigoveze." },
    silver_gildingbrush = { name = "Srebrn čopič za pozlačevanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn čopič za pozlačevanje za knjigoveze." },
    gilded_gildingbrush = { name = "Pozlačen čopič za pozlačevanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen čopič za pozlačevanje za knjigoveze." },
    jewel_set_gildingbrush = { name = "Draguljast čopič za pozlačevanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast čopič za pozlačevanje za knjigoveze." },
    royal_sovereign_gildingbrush = { name = "Kraljevski suveren čopič za pozlačevanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren čopič za pozlačevanje z biseri za krono." },
}
local BUILDINGS = {
    gildingbrush_workshop = { name = "Gildingbrush delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gildingbrush_house = { name = "Gildingbrush hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gildingbrush_atelier = { name = "Mojstrski gildingbrush atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gildingbrush_palace = { name = "Suverena gildingbrush palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GildingBrushMaker.ironStock=12; GildingBrushMaker.bronzeStock=10; GildingBrushMaker.woodStock=14; GildingBrushMaker.leatherStock=12; GildingBrushMaker.silverStock=8; GildingBrushMaker.goldStock=6; GildingBrushMaker.jewelStock=4; GildingBrushMaker.pearlStock=4
GildingBrushMaker.productStock = {}; GildingBrushMaker.buildings = {}; GildingBrushMaker.maker = nil; GildingBrushMaker.activeMaking = {}; GildingBrushMaker.totalProducts = 0; GildingBrushMaker.dayTimer = 0
function GildingBrushMaker.init() GildingBrushMaker.ironStock=12; GildingBrushMaker.bronzeStock=10; GildingBrushMaker.woodStock=14; GildingBrushMaker.leatherStock=12; GildingBrushMaker.silverStock=8; GildingBrushMaker.goldStock=6; GildingBrushMaker.jewelStock=4; GildingBrushMaker.pearlStock=4; GildingBrushMaker.productStock={}; GildingBrushMaker.buildings={}; GildingBrushMaker.maker=nil; GildingBrushMaker.activeMaking={}; GildingBrushMaker.totalProducts=0; GildingBrushMaker.dayTimer=0; print("[GildingBrushMaker] Royal Gilding Brush Maker System initialized (6 products, 4 buildings)") end
function GildingBrushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GildingBrushMaker.maker={name=n or ("Čopičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čopičar najet: %s (spretnost: %d)",GildingBrushMaker.maker.name,s),"success") end; return true end
function GildingBrushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GildingBrushMaker.build(id) local ok,e=GildingBrushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GildingBrushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GildingBrushMaker.getQualityBonus() local b=0; for _,bd in ipairs(GildingBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GildingBrushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GildingBrushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GildingBrushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GildingBrushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GildingBrushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GildingBrushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GildingBrushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GildingBrushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GildingBrushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GildingBrushMaker.buildings==0 then return false,"Potrebna čopična delavnica" end; if not GildingBrushMaker.maker then return false,"Potreben čopičar" end; return true end
function GildingBrushMaker.make(pt,qty) qty=qty or 1; local ok,e=GildingBrushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GildingBrushMaker.ironStock=GildingBrushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GildingBrushMaker.bronzeStock=GildingBrushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GildingBrushMaker.woodStock=GildingBrushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GildingBrushMaker.leatherStock=GildingBrushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GildingBrushMaker.silverStock=GildingBrushMaker.silverStock-d.silverCost*qty end; if d.goldCost then GildingBrushMaker.goldStock=GildingBrushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GildingBrushMaker.jewelStock=GildingBrushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GildingBrushMaker.pearlStock=GildingBrushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GildingBrushMaker.maker then t=math.max(1,t-math.floor(GildingBrushMaker.maker.skill/13)) end; table.insert(GildingBrushMaker.activeMaking,{id="gildingbrush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GildingBrushMaker.completeMaking(m) local q=1.0+(GildingBrushMaker.getQualityBonus()/100); if GildingBrushMaker.maker then q=q+(GildingBrushMaker.maker.skill/140) end; q=math.min(2.5,q); GildingBrushMaker.productStock[m.productType]=(GildingBrushMaker.productStock[m.productType] or 0)+m.quantity; GildingBrushMaker.totalProducts=GildingBrushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GildingBrushMaker.maker then GildingBrushMaker.maker.itemsMade=GildingBrushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GildingBrushMaker.maker.skill=math.min(100,GildingBrushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čopič izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gildingbrush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GildingBrushMaker.update(dt) if not _G.state then return end; GildingBrushMaker.dayTimer=GildingBrushMaker.dayTimer+dt; if GildingBrushMaker.dayTimer>=30 then GildingBrushMaker.dayTimer=0; for i=#GildingBrushMaker.activeMaking,1,-1 do local m=GildingBrushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GildingBrushMaker.completeMaking(m); table.remove(GildingBrushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GildingBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GildingBrushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GildingBrushMaker.getStats() return {ironStock=GildingBrushMaker.ironStock,bronzeStock=GildingBrushMaker.bronzeStock,woodStock=GildingBrushMaker.woodStock,leatherStock=GildingBrushMaker.leatherStock,silverStock=GildingBrushMaker.silverStock,goldStock=GildingBrushMaker.goldStock,jewelStock=GildingBrushMaker.jewelStock,pearlStock=GildingBrushMaker.pearlStock,productStock=GildingBrushMaker.productStock,numBuildings=#GildingBrushMaker.buildings,hasMaker=GildingBrushMaker.maker~=nil,makerName=GildingBrushMaker.maker and GildingBrushMaker.maker.name or "—",makerSkill=GildingBrushMaker.maker and GildingBrushMaker.maker.skill or 0,activeMaking=#GildingBrushMaker.activeMaking,totalProducts=GildingBrushMaker.totalProducts} end
return GildingBrushMaker
